    m.insert("cli.helpers.export_options".into(), " --ral-export-all <name> ส่งออก run alias ทั้งหมดไปยัง <name>.ntc.ral\n --ral-export-select <name> เลือก alias เพื่อส่งออก\n --ral-import <file> นำเข้า alias จากไฟล์ .ntc.ral\n --igcare-export-all <name> ส่งออกการตั้งค่า ignore/care ทั้งหมด\n --igcare-export-select <name> เลือกหมวดหมู่เพื่อส่งออก\n --igcare-import <file> นำเข้าการตั้งค่าจากไฟล์ .ntc.igcare\n".into());
